input.content:
import sys
import openpyxl

p = sys.argv[1]
wb = openpyxl.load_workbook(p, data_only=False)
for ws in wb.worksheets:
    print("===", repr(ws.title), ws.dimensions, "merged:", [str(r) for r in ws.merged_cells.ranges])
    for row in ws.iter_rows():
        out = []
        for c in row:
            if c.value is not None:
                out.append("%s=%r [%s]" % (c.coordinate, c.value, c.number_format))
        if out:
            print("   " + " | ".join(out))
    print("   images:", len(getattr(ws, "_images", [])))

